  // where the line of sight through this point meets the cutting plane (camera coordinates)\n  // @capleak: it has to meet it on the way from the eye to this point …\n  vec3 q = vEye;\n  if (uOrtho > 0.5) {\n    if (uPlane.z > -1e-5) discard;\n    q.z -= (dot(uPlane.xyz, vEye) + uPlane.w) / uPlane.z;\n  } else {\n    float along = dot(uPlane.xyz, vEye);\n    if (abs(along) < 1e-9) discard;\n    float t = -uPlane.w / along;\n    if (t <= 0.0 || t > 1.0001) discard;\n    q = vEye * t;\n  }\n  // … and within the box around the body: the cut face lies where the plane goes through the body\n  vec3 ql = (uToLocal * vec4(q, 1.0)).xyz;\n  if (any(lessThan(ql, uBoxMin)) || any(greaterThan(ql, uBoxMax))) discard;\n  // across the lines, in steps: a line at every whole number\n  float h = dot(q, uAcross) / uStep + uPhase;\n  float perPx = max(fwidth(h), 1e-6);\n  float px = abs(fract(h + 0.5) - 0.5) / perPx;\n  float ink = 1.0 - smoothstep(uHalf - 0.5, uHalf + 0.5, px);\n  // seen nearly edge on the lines would run into each other: their share of the face instead\n  ink = mix(ink, clamp(2.0 * uHalf * perPx, 0.0, 1.0), smoothstep(0.2, 0.45, perPx));\n  gl_FragColor = vec4(mix(uFill, uInk, ink * uHatch), 1.0);\n  #include <tonemapping_fragment>\n  #include <colorspace_fragment>\n}","text/plain"," off","teacher","#2e9d57","dp.lineSecond","#22305e","option","oBBooBBo","site.confirm","treeitem","ad.all","body","task-x","sec:wp","task.n.print","nearest","extend","roof.sides.p","auto.door.hingeTip","done","nav-size-tag","stage-view","trip.cancelTip","lb.rename","chat.mode.preparing","win.expandTip","rise","ot.k.plane","pointerover","addPoint","presetParam.thick","btn.close","Spacebar","flow.top.height","(prefers-reduced-motion: reduce)","opt.stairSteps","af.lightsMove","imgsz:h","ot.deleteBuilding","cmd icon labelled","imageCalibrate","ot.k.other","site.fileSize","modal site-map","cchat-warn","aismart.placeNote","planView","point","short","./react-dom-CcokwLNm.js","body-row","dsh.z